<template>
  <div class="cart-page">
    <div class="cart-container">
      <div class="cart-heading"><span class="eyebrow">NÚCLEO / SUA SELEÇÃO</span><h1>Seu próximo projeto começa aqui.</h1><p>Revise os componentes antes de continuar.</p></div>
      <div v-if="cartStore.error" class="cart-alert">{{ cartStore.error }}</div>
      <div v-if="cartStore.cart.items.length === 0" class="empty-cart">
        <div class="empty-copy"><span class="eyebrow">UMA BOA MONTAGEM COMEÇA COM BOAS ESCOLHAS</span><h2>Seu carrinho está vazio.</h2><p>Explore uma seleção de componentes pensada para desempenho e presença em cada detalhe.</p><router-link to="/products">Explorar catálogo <v-icon size="18">mdi-arrow-right</v-icon></router-link></div><div class="empty-visual"><img src="/showroom/assembly-03.png" alt="Computador montado com gabinete preto e detalhes em madeira" /></div>
      </div>
      <div v-else class="cart-layout">
        <section class="cart-items" aria-label="Produtos no carrinho">
          <article v-for="item in cartStore.cart.items" :key="item.id" class="cart-item">
            <router-link :to="'/products/' + item.id" class="cart-item-image"><img :src="item.images[0]" :alt="item.name" /></router-link>
            <div class="cart-item-info"><span>{{ item.brand }}</span><router-link :to="'/products/' + item.id">{{ item.name }}</router-link><small>Imagem ilustrativa</small></div>
            <div class="cart-item-controls"><span class="small-label">Quantidade</span><div class="stepper"><button type="button" :disabled="item.quantity <= 1" :aria-label="'Diminuir quantidade de ' + item.name" @click="updateQuantity(item.id,item.quantity-1)">−</button><strong>{{ item.quantity }}</strong><button type="button" :aria-label="'Aumentar quantidade de ' + item.name" @click="updateQuantity(item.id,item.quantity+1)">+</button></div></div>
            <div class="cart-item-price"><span class="small-label">Total</span><strong>{{ formatCurrency(item.price * item.quantity) }}</strong><button type="button" :aria-label="'Remover ' + item.name" @click="removeItem(item.id)">Remover</button></div>
          </article>
          <router-link class="continue-link" to="/products"><v-icon size="17">mdi-arrow-left</v-icon> Continuar comprando</router-link>
        </section>
        <aside class="cart-aside">
          <section class="summary-card"><span class="eyebrow">VISÃO GERAL</span><h2>Resumo da seleção</h2><div><span>{{ cartStore.totalItems }} {{ cartStore.totalItems === 1 ? 'item' : 'itens' }}</span><strong>{{ formatCurrency(cartStore.cart.subtotal) }}</strong></div><div><span>Entrega</span><strong>Não simulada</strong></div><div class="summary-total"><span>Subtotal dos produtos</span><strong>{{ formatCurrency(cartStore.cart.subtotal) }}</strong></div><router-link to="/checkout" class="checkout-link">Revisar demonstração <v-icon size="19">mdi-arrow-right</v-icon></router-link><p class="summary-note">Preços ilustrativos. Você poderá concluir uma simulação, sem compra ou pagamento.</p></section>
          <section class="utility-card"><h3>Entrega e promoções</h3><p class="summary-note">Este protótipo não calcula frete nem aplica cupons. Essas integrações ficam como pontos de extensão do template.</p><router-link to="/entrega">Sobre a demonstração</router-link></section>
        </aside>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { useCartStore } from '@/stores/cart';
const cartStore=useCartStore();
const formatCurrency=(value:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(value);
async function updateQuantity(id:string,quantity:number){cartStore.error=null;try{await cartStore.updateItemQuantity(id,quantity)}catch(error){cartStore.error=error instanceof Error?error.message:'Não foi possível alterar a quantidade.'}}
async function removeItem(id:string){cartStore.error=null;try{await cartStore.removeFromCart(id)}catch{cartStore.error='Não foi possível remover o item.'}}
</script>

